const issues = items.map(i => i.json);
const lines = issues.map(issue => {
  const f = issue.fields || {};
  return `- ${issue.key} | ${f.issuetype?.name || 'Unknown'} | status: ${f.status?.name || 'Unknown'} | points: ${f.customfield_10016 ?? 'n/a'} | priority: ${f.priority?.name || 'n/a'} | summary: ${f.summary || ''}`;
}).join('\n');

return [{ json: { issueCount: issues.length, summaryText: lines } }];
